// Generated by `just generate` from `src/plugins/claudetto/slices/minispec/domain/text.ts`. Edit the source and run `just generate`.
// Small text rules of the CLI: names, the nearest command, and color.

import {
  NAME_CHARS_MAX,
  NAME_PATTERN,
  SUGGEST_DISTANCE_MAX,
} from "../limits.ts";
import { DID_YOU_MEAN, NAME_INVALID, NAME_TOO_LONG } from "../prompts.ts";

/** The problem with a name, or `null` when the name is good. */
export const nameIssue = (name: string, what: string): string | null => {
  if (name.length > NAME_CHARS_MAX) return NAME_TOO_LONG({ what });
  return NAME_PATTERN.test(name) ? null : NAME_INVALID({ name, what });
};

/** The hint for a near name: a sentence that starts with a space, or an empty text when no name is near. */
export const hintOf = (near: string | undefined): string =>
  near ? ` ${DID_YOU_MEAN({ near })}` : "";

/** The edit distance of two words. */
const distance = (a: string, b: string): number => {
  let prev = Array.from({ length: b.length + 1 }, (_, i) => i);
  for (let i = 1; i <= a.length; i++) {
    const row = [i];
    for (let j = 1; j <= b.length; j++)
      row.push(
        Math.min(
          (prev[j] ?? 0) + 1,
          (row[j - 1] ?? 0) + 1,
          (prev[j - 1] ?? 0) + (a[i - 1] === b[j - 1] ? 0 : 1),
        ),
      );
    prev = row;
  }
  return prev[b.length] ?? 0;
};

/** The command in `commands` that is nearest to `word`, or `undefined` when none is near. */
export const nearest = (
  word: string,
  commands: readonly string[],
): string | undefined => {
  let best: string | undefined;
  let bestDistance = SUGGEST_DISTANCE_MAX + 1;
  for (const c of commands) {
    const d = distance(word, c);
    if (d < bestDistance) {
      best = c;
      bestDistance = d;
    }
  }
  return best;
};

/** True when color is allowed: the stream is a terminal, `NO_COLOR` is not set, and `--no-color` is not given. */
export const colorOn = (
  isTerminal: boolean,
  noColorEnv: string | undefined,
  noColorFlag: boolean,
): boolean => isTerminal && !noColorFlag && (noColorEnv ?? "") === "";

const CODES = { red: 31, green: 32, bold: 1 } as const;

/** `text` in the color `color` when `on` is true, and `text` as it is when `on` is false. */
export const paint = (
  on: boolean,
  color: keyof typeof CODES,
  text: string,
): string => (on ? `\u001b[${CODES[color]}m${text}\u001b[0m` : text);
